package com.hms.website;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/website/content") public class WebsiteContentController {private final TenantRepository tenants;private final WebsiteContentRepository content;public WebsiteContentController(TenantRepository t,WebsiteContentRepository c){tenants=t;content=c;} @GetMapping public List<WebsiteContentItem> list(@PathVariable String tenantSlug,@RequestParam(required=false) ContentStatus status){UUID t=tenant(tenantSlug);return status==null?content.findAllByTenantIdOrderByUpdatedAtDesc(t):content.findAllByTenantIdAndStatusOrderByPublishedAtDesc(t,status);} @GetMapping("/public") public List<WebsiteContentItem> publicContent(@PathVariable String tenantSlug,@RequestParam(required=false) ContentCategory category){UUID t=tenant(tenantSlug);return content.findAllByTenantIdAndStatusOrderByPublishedAtDesc(t,ContentStatus.PUBLISHED).stream().filter(x->category==null||x.getCategory()==category).toList();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public WebsiteContentItem create(@PathVariable String tenantSlug,@Valid @RequestBody CreateContentRequest r){return content.save(new WebsiteContentItem(tenant(tenantSlug),r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
